package com.library.catalog.controller;
import com.library.catalog.dto.CatalogDtos.*; import com.library.catalog.entity.*; import com.library.catalog.repository.CatalogRepositories.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequiredArgsConstructor public class LookupController{private final Authors authors;private final Categories categories;private final Publishers publishers;
 @GetMapping("/api/authors")List<LookupResponse>authors(){return authors.findAll().stream().map(x->new LookupResponse(x.getId(),x.getName(),x.getBiography())).toList();}@PostMapping("/api/authors")@PreAuthorize("hasAnyRole('ADMIN','LIBRARIAN')")Author author(@Valid @RequestBody NameRequest r){return authors.save(Author.builder().name(r.name()).biography(r.biography()).photoUrl(r.photoUrl()).build());}@DeleteMapping("/api/authors/{id}")@PreAuthorize("hasRole('ADMIN')")void delAuthor(@PathVariable Long id){authors.deleteById(id);}
 @GetMapping("/api/categories")List<LookupResponse>categories(){return categories.findAll().stream().map(x->new LookupResponse(x.getId(),x.getName(),x.getDescription())).toList();}@PostMapping("/api/categories")@PreAuthorize("hasAnyRole('ADMIN','LIBRARIAN')")Category category(@Valid @RequestBody NameRequest r){return categories.save(Category.builder().name(r.name()).description(r.description()).build());}@DeleteMapping("/api/categories/{id}")@PreAuthorize("hasRole('ADMIN')")void delCategory(@PathVariable Long id){categories.deleteById(id);}
 @GetMapping("/api/publishers")List<LookupResponse>publishers(){return publishers.findAll().stream().map(x->new LookupResponse(x.getId(),x.getName(),x.getAddress())).toList();}@PostMapping("/api/publishers")@PreAuthorize("hasAnyRole('ADMIN','LIBRARIAN')")Publisher publisher(@Valid @RequestBody NameRequest r){return publishers.save(Publisher.builder().name(r.name()).address(r.address()).website(r.website()).build());}
}

